+	today := now.Format("2006-01-02")
+	yesterday := now.AddDate(0, 0, -1).Format("2006-01-02")
+	older := now.AddDate(0, 0, -5).Format("2006-01-02")
+	future := now.AddDate(0, 0, 2).Format("2006-01-02")
+
+	tests := []struct {
+		name     string
+		input    string
+		contains string
+		excludes string
+	}{
+		{"today", today, "(today)", ""},
+		{"yesterday", yesterday, "(yesterday)", ""},
+		{"older", older, "", "(today)"},
+		{"future", future, "", "(today)"},
+		{"invalid", "bad-date", "bad-date", ""},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			t.Parallel()
+			got := formatCommitDate(tt.input)
+			if tt.contains != "" && !containsStr(got, tt.contains) {
+				t.Errorf("formatCommitDate(%q) = %q, want to contain %q", tt.input, got, tt.contains)
+			}
+			if tt.excludes != "" && containsStr(got, tt.excludes) {
+				t.Errorf("formatCommitDate(%q) = %q, should not contain %q", tt.input, got, tt.excludes)
+			}
+		})
+	}
+}
+
+func containsStr(s, sub string) bool {
+	return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
+		(len(s) > 0 && stringContains(s, sub)))
+}
+
+func stringContains(s, sub string) bool {
+	for i := 0; i <= len(s)-len(sub); i++ {
+		if s[i:i+len(sub)] == sub {
+			return true
+		}
+	}
+	return false
+}"},{"sha":"3a853f1adbfa82987ec3d9e8d81fe1b505103c86","filename":"cmd/entire/cli/activity_render.go","status":"added","additions":772,"deletions":0,"changes":772,"blob_url":"https://github.com/entireio/cli/blob/9b1613d60137d0214f4c09f70001b64e92c09e26/cmd%2Fentire%2Fcli%2Factivity_render.go","raw_url":"https://github.com/entireio/cli/raw/9b1613d60137d0214f4c09f70001b64e92c09e26/cmd%2Fentire%2Fcli%2Factivity_render.go","contents_url":"https://api.github.com/repos/entireio/cli/contents/cmd%2Fentire%2Fcli%2Factivity_render.go?ref=9b1613d60137d0214f4c09f70001b64e92c09e26","patch":"@@ -0,0 +1,772 @@
